import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  const cardRoot = new THREE.Group();
  const owned = [];
  const timelines = [];
  const primitiveCleanups = [];
  let disposed = false;
  let loadedTexture = null;

  group.userData.handlers = {};

  const cardWidth = 2.5;
  const cardHeight = 1.56;
  const frameDepth = 0.025;

  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1
  });
  owned.push(material);

  const geometry = new THREE.PlaneGeometry(cardWidth, cardHeight);
  owned.push(geometry);

  const imagePlane = new THREE.Mesh(geometry, material);
  imagePlane.position.z = 0;
  cardRoot.add(imagePlane);

  const backingMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 1
  });
  owned.push(backingMaterial);

  const backingGeometry = new THREE.BoxGeometry(
    cardWidth + 0.08,
    cardHeight + 0.08,
    frameDepth
  );
  owned.push(backingGeometry);

  const backing = new THREE.Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.035;
  cardRoot.add(backing);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0
  });
  owned.push(edgeMaterial);

  const edgeGeometry = new THREE.BoxGeometry(0.035, cardHeight + 0.12, 0.04);
  owned.push(edgeGeometry);

  const accentEdge = new THREE.Mesh(edgeGeometry, edgeMaterial);
  accentEdge.position.set(cardWidth * 0.5 + 0.025, 0, 0.035);
  cardRoot.add(accentEdge);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.position.set(-cardWidth * 0.5 + 0.18, -cardHeight * 0.5 + 0.22, 0.075);
    cardRoot.add(textObject);
  }

  group.add(cardRoot);

  const entrance = gsap.fromTo(
    cardRoot.position,
    { y: 0.4, opacity: 0 },
    {
      y: 0,
      opacity: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );
  timelines.push(entrance);

  const settle = gsap.timeline();
  settle.fromTo(
    cardRoot.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }
  );
  timelines.push(settle);

  const setFocused = (focused) => {
    if (disposed) return;
    gsap.to(edgeMaterial, {
      opacity: focused ? 1 : 0,
      duration: 0.18,
      ease: 'power2.out'
    });
  };

  group.userData.handlers.focus = () => setFocused(true);
  group.userData.handlers.blur = () => setFocused(false);

  group.userData.handlers.hover = (active) => {
    if (disposed) return;
    const hovered = typeof active === 'boolean' ? active : true;

    gsap.to(cardRoot.position, {
      y: hovered ? 0.15 : 0,
      duration: 0.3,
      ease: 'power2.out'
    });

    gsap.to(cardRoot.rotation, {
      x: hovered ? -0.035 : 0,
      y: hovered ? 0.025 : 0,
      duration: 0.3,
      ease: 'power2.out'
    });

    setFocused(hovered);
  };

  group.userData.handlers.click = () => {
    if (disposed) return;

    const press = gsap.timeline();
    press.to(cardRoot.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    press.to(cardRoot.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.28,
      ease: 'back.out(2)'
    });
    timelines.push(press);

    ctx.emit('hub-journal.select', {
      node: config.id,
      label: 'Journal 2'
    });
  };

  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const primitive of primitiveSpecs) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') continue;

    const result = ctx.primitives[primitive.name](group, primitive.params ?? {});
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      loadedTexture = texture;
      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    if (loadedTexture) loadedTexture.dispose?.();

    for (const object of [group, cardRoot]) {
      object.traverse?.((child) => {
        if (child.geometry && !owned.includes(child.geometry)) {
          child.geometry.dispose?.();
        }
      });
    }

    for (const resource of owned) {
      resource.dispose?.();
    }

    group.clear();
  };

  return group;
}
